package com.ticketing.system.sales.application.port.out;
import com.ticketing.system.sales.domain.OrderReceipt;

import java.util.List;
import java.util.Optional;

import com.ticketing.system.shared.dto.GlobalHistoryFiltersDTO;
import com.ticketing.system.shared.IRepository;

/**
 * Aggregate-root entry point for the {@link OrderReceipt} aggregate. Receipt ids are assigned by the
 * application from {@link #nextId()}, not generated by the store.
 */
public interface OrderReceiptRepository extends IRepository<OrderReceipt, Integer> {

    /**
     * Mints the id for a new receipt.
     *
     * @return a positive id that no stored receipt has; on the JPA adapter the sequence continues from
     *     the highest stored id, so a restart does not repeat one
     */
    int nextId();
    
    /** Stores the receipt, inserting it or updating the stored receipt with the same id. */
    void save(OrderReceipt orderReceipt);

    /** Returns the receipt with this id, or empty if there is none. */
    Optional<OrderReceipt> findByOrderReceiptId(int orderReceiptId);

    /**
     * Returns the member's own receipts (UC-16). Guest receipts are never returned.
     *
     * @return the member's receipts, empty if there are none
     */
    List<OrderReceipt> findByHolderUserId(int holderUserId);

    /**
     * Returns the receipts with at least one line for any of the events.
     *
     * @param eventIds the events to match; {@code null} or empty matches nothing
     * @return the matching receipts, each once
     */
    List<OrderReceipt> findByEventIds(List<Integer> eventIds);

    /**
     * Returns the receipts that match the admin filters of the global purchase history (UC-31). A
     * receipt matches when it satisfies every filter that is set: the buyer, at least one line for one
     * of the events, and a purchase time from the start of {@code fromDate} up to the end of
     * {@code toDate}. The company filter is not applied, since a receipt does not know company
     * ownership.
     *
     * @param filters the filters; {@code null} matches every receipt, and an empty event list matches
     *     none
     */
    List<OrderReceipt> findGlobal(GlobalHistoryFiltersDTO filters);

    /** Returns the receipts with at least one line for the event, each once. */
    List<OrderReceipt> findByEventId(int eventId);
}
